function makeBookSummary(book) {
  if (book === null || typeof book !== 'object' || Array.isArray(book)) {
    throw new TypeError('book must be an object');
  }
  if (typeof book.title !== 'string' || book.title.trim() === '') {
    throw new TypeError('title must be a non-empty string');
  }
  if (!Array.isArray(book.authors) || book.authors.length === 0) {
    throw new TypeError('authors must be a non-empty array');
  }
  const authors = book.authors.map((author) => {
    if (typeof author !== 'string' || author.trim() === '') {
      throw new TypeError('each author must be a non-empty string');
    }
    return author.trim();
  });
  if (!Number.isInteger(book.pageCount) || book.pageCount < 1 || book.pageCount > 100000) {
    throw new TypeError('pageCount must be an integer from 1 through 100000');
  }

  let size = 'short';
  if (book.pageCount > 500) size = 'long';
  else if (book.pageCount >= 200) size = 'medium';

  return {
    heading: book.title.trim(),
    byline: `By ${authors.join(', ')}`,
    size
  };
}

module.exports = { makeBookSummary };

