'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['makeBookSummary']);
const { makeBookSummary } = api;

assert.deepStrictEqual(
  makeBookSummary({ title: '  Dune  ', authors: [' Frank Herbert '], pageCount: 199 }),
  { heading: 'Dune', byline: 'By Frank Herbert', size: 'short' }
);
assert.deepStrictEqual(
  makeBookSummary({ title: 'Book', authors: [' A ', 'B', ' A '], pageCount: 200, ignored: true }),
  { heading: 'Book', byline: 'By A, B, A', size: 'medium' }
);
assert.deepStrictEqual(makeBookSummary({ title: 'M', authors: ['X'], pageCount: 499 }), {
  heading: 'M', byline: 'By X', size: 'medium'
});
assert.deepStrictEqual(makeBookSummary({ title: 'L', authors: ['X'], pageCount: 500 }), {
  heading: 'L', byline: 'By X', size: 'long'
});
assert.deepStrictEqual(makeBookSummary({ title: 'Max', authors: ['X'], pageCount: 100000 }), {
  heading: 'Max', byline: 'By X', size: 'long'
});

const input = { title: '  Stable  ', authors: [' One ', 'Two'], pageCount: 1 };
const authorsBefore = input.authors.slice();
const result = makeBookSummary(input);
assert.deepStrictEqual(input, { title: '  Stable  ', authors: authorsBefore, pageCount: 1 });
assert.notStrictEqual(result, input);
assert.deepStrictEqual(result, { heading: 'Stable', byline: 'By One, Two', size: 'short' });
result.heading = 'changed';
assert.equal(input.title, '  Stable  ');

for (const bad of [undefined, null, [], 'book', 3, new Date()]) {
  assert.throws(() => makeBookSummary(bad), TypeError);
}
for (const badTitle of [undefined, null, '', '   ', 7, []]) {
  assert.throws(() => makeBookSummary({ title: badTitle, authors: ['A'], pageCount: 10 }), TypeError);
}
for (const badAuthors of [undefined, null, 'A', [], [42], ['A', ''], ['A', '  '], ['A', null]]) {
  assert.throws(() => makeBookSummary({ title: 'T', authors: badAuthors, pageCount: 10 }), TypeError);
}
for (const badCount of [undefined, null, 0, -1, 1.5, 100001, NaN, Infinity, '10']) {
  assert.throws(() => makeBookSummary({ title: 'T', authors: ['A'], pageCount: badCount }), TypeError);
}

